// Build period boundaries in the same timezone as request validation and daily
// archiving. SQL only compares Unix timestamps: database session timezones and
// daylight-saving changes cannot shift a log or a summary into another period.
// The caller restricts rows to timeRange; names and boundaries are generated by
// the server, not supplied as SQL by the client.
func reconciliationPeriodExpression(granularity, column string, timeRange reconciliationTimeRange) string {
	if timeRange.start >= timeRange.end {
		// A timezone can skip an entire civil date (Apia, 2011-12-30).
		// The WHERE range is empty; still emit a valid GROUP BY expression on
		// every supported dialect rather than an empty "CASE END".
		return "CASE WHEN 1 = 1 THEN '' END"
	}
	period := reconciliationLocalDayStart(timeRange.start)
	if granularity == "month" {
		period = common.ReconciliationDateStart(period.Year(), period.Month(), 1, time.Local)
	}
	var builder strings.Builder
	builder.WriteString("CASE")
	for period.Unix() < timeRange.end {
		next := common.ReconciliationNextDay(period)
		label := period.Format(time.DateOnly)
		if granularity == "month" {
			next = common.ReconciliationDateStart(period.Year(), period.Month()+1, 1, time.Local)
			label = period.Format("2006-01")
		}
		fmt.Fprintf(&builder, " WHEN %s < %d THEN '%s'", column, next.Unix(), label)
		period = next
	}
	builder.WriteString(" END")
	return builder.String()
}

type reconciliationTimeRange struct {
	start int64
	end   int64
}

func reconciliationArchiveEndExclusive(state *ReconciliationArchiveState) int64 {
	through := reconciliationLocalDayStart(state.ArchivedThrough)
	return common.ReconciliationNextDay(through).Unix()
}

func splitReconciliationRanges(
	filter dto.ReconciliationFilter,
	state *ReconciliationArchiveState,
) (*reconciliationTimeRange, []reconciliationTimeRange) {
	if state == nil {
		return nil, []reconciliationTimeRange{{start: filter.StartTimestamp, end: filter.EndTimestamp}}
	}

	summaryStart := max(filter.StartTimestamp, state.SummaryStart)
	summaryEnd := min(filter.EndTimestamp, reconciliationArchiveEndExclusive(state))
	if summaryStart >= summaryEnd {
		return nil, []reconciliationTimeRange{{start: filter.StartTimestamp, end: filter.EndTimestamp}}
	}

	rawRanges := make([]reconciliationTimeRange, 0, 2)
	if filter.StartTimestamp < summaryStart {
		rawRanges = append(rawRanges, reconciliationTimeRange{start: filter.StartTimestamp, end: summaryStart})
	}
	if summaryEnd < filter.EndTimestamp {
		rawRanges = append(rawRanges, reconciliationTimeRange{start: summaryEnd, end: filter.EndTimestamp})
	}
	return &reconciliationTimeRange{start: summaryStart, end: summaryEnd}, rawRanges
}

func appendReconciliationFilters(
	builder *strings.Builder,
	args *[]any,
	filter dto.ReconciliationFilter,
	alias string,
) {
	if filter.UserID > 0 {
		builder.WriteString(" AND " + alias + ".user_id = ?")
		*args = append(*args, filter.UserID)
	}
	if filter.ModelName != "" {
		builder.WriteString(" AND " + alias + ".model_name = ?")
		*args = append(*args, filter.ModelName)
	}
}

func buildReconciliationRawSourceSQL(
	filter dto.ReconciliationFilter,
	timeRange reconciliationTimeRange,
	includeAggregates bool,
) (string, []any) {
	periodExpression := reconciliationPeriodExpression(filter.Granularity, "l.created_at", timeRange)
	selectExpression := fmt.Sprintf("l.user_id, l.model_name, %s AS period", periodExpression)
	if includeAggregates {
		selectExpression = fmt.Sprintf(
			"l.user_id, COALESCE(MAX(NULLIF(l.username, '')), '') AS username, l.model_name, %s AS period, SUM(l.quota) AS quota",
			periodExpression,
		)
	}

	var builder strings.Builder
	fmt.Fprintf(&builder, "SELECT %s FROM logs AS l WHERE l.type = ? AND l.created_at >= ? AND l.created_at < ?", selectExpression)
	args := []any{LogTypeConsume, timeRange.start, timeRange.end}
	appendReconciliationFilters(&builder, &args, filter, "l")
	fmt.Fprintf(&builder, " GROUP BY l.user_id, l.model_name, %s", periodExpression)
	return builder.String(), args
}

func buildReconciliationSummarySourceSQL(
	filter dto.ReconciliationFilter,
	timeRange reconciliationTimeRange,
	includeAggregates bool,
) (string, []any) {
	periodExpression := reconciliationPeriodExpression(filter.Granularity, "s.day_start", timeRange)
	selectExpression := fmt.Sprintf("s.user_id, s.model_name, %s AS period", periodExpression)
	if includeAggregates {
		selectExpression = fmt.Sprintf(
			"s.user_id, COALESCE(MAX(NULLIF(s.username, '')), '') AS username, s.model_name, %s AS period, SUM(s.quota) AS quota",
			periodExpression,
		)
	}

	var builder strings.Builder
	fmt.Fprintf(&builder, "SELECT %s FROM reconciliation_daily_summaries AS s WHERE s.day_start >= ? AND s.day_start < ?", selectExpression)
	args := []any{timeRange.start, timeRange.end}
	appendReconciliationFilters(&builder, &args, filter, "s")
	fmt.Fprintf(&builder, " GROUP BY s.user_id, s.model_name, %s", periodExpression)
	return builder.String(), args
}

func buildReconciliationGroupedSQL(
	ctx context.Context,
	filter dto.ReconciliationFilter,
	includeAggregates bool,
) (string, []any, error) {
	state, err := GetReconciliationArchiveState(ctx)
	if err != nil {
		return "", nil, err
	}
	summaryRange, rawRanges := splitReconciliationRanges(filter, state)
	sources := make([]string, 0, len(rawRanges)+1)
	args := make([]any, 0, (len(rawRanges)+1)*3)
	for _, timeRange := range rawRanges {
		sourceSQL, sourceArgs := buildReconciliationRawSourceSQL(filter, timeRange, includeAggregates)
		sources = append(sources, sourceSQL)
		args = append(args, sourceArgs...)
	}
	if summaryRange != nil {
		sourceSQL, sourceArgs := buildReconciliationSummarySourceSQL(filter, *summaryRange, includeAggregates)
		sources = append(sources, sourceSQL)
		args = append(args, sourceArgs...)
	}
	if len(sources) == 0 {
		return "", nil, errors.New("reconciliation query has no data source")
	}

	unionSQL := strings.Join(sources, " UNION ALL ")
	if includeAggregates {
		return "SELECT user_id, COALESCE(MAX(NULLIF(username, '')), '') AS username, model_name, period, SUM(quota) AS quota " +
			"FROM (" + unionSQL + ") AS reconciliation_sources " +
			"GROUP BY user_id, model_name, period", args, nil
	}
	return "SELECT user_id, model_name, period FROM (" + unionSQL + ") AS reconciliation_sources " +
		"GROUP BY user_id, model_name, period", args, nil
}

func GetReconciliationBillsSummary(
	ctx context.Context,
	filter dto.ReconciliationFilter,
) (int64, int64, error) {
	groupedSQL, args, err := buildReconciliationGroupedSQL(ctx, filter, true)
	if err != nil {
		return 0, 0, err
	}
	var result struct {
		Total      int64
		TotalQuota int64
	}
	err = LOG_DB.WithContext(ctx).
		Raw("SELECT COUNT(*) AS total, COALESCE(SUM(quota), 0) AS total_quota FROM ("+groupedSQL+") AS reconciliation_groups", args...).
		Scan(&result).Error
	return result.Total, result.TotalQuota, err
}

func CountReconciliationBills(ctx context.Context, filter dto.ReconciliationFilter) (int64, error) {
	total, _, err := GetReconciliationBillsSummary(ctx, filter)
	return total, err
}

// Keep totals and page rows in one statement snapshot. Derived tables and a
// LEFT JOIN also work on MySQL 5.7 (no window functions or CTEs required), and
// preserve totals when the requested page is empty or beyond the last page.
func GetReconciliationBillsPage(ctx context.Context, filter dto.ReconciliationFilter, offset, limit int) ([]dto.ReconciliationBill, int64, int64, error) {
	groupedSQL, args, err := buildReconciliationGroupedSQL(ctx, filter, true)
	if err != nil {
		return nil, 0, 0, err
	}
	querySQL := "SELECT totals.total, totals.total_quota, paged.* FROM (" +
		"SELECT COUNT(*) AS total, COALESCE(SUM(quota), 0) AS total_quota FROM (" + groupedSQL + ") AS all_groups" +
		") AS totals LEFT JOIN (SELECT page_groups.*, 1 AS has_item FROM (" + groupedSQL + ") AS page_groups" +
		" ORDER BY period DESC, username ASC, model_name ASC, user_id ASC LIMIT ? OFFSET ?" +
		") AS paged ON 1 = 1 ORDER BY paged.period DESC, paged.username ASC, paged.model_name ASC, paged.user_id ASC"
	queryArgs := append(append([]any(nil), args...), args...)
	queryArgs = append(queryArgs, limit, offset)
	var rows []struct {
		dto.ReconciliationBill
		Total      int64
		TotalQuota int64
		HasItem    *int
	}
	if err := LOG_DB.WithContext(ctx).Raw(querySQL, queryArgs...).Scan(&rows).Error; err != nil {
		return nil, 0, 0, err
	}
	items := make([]dto.ReconciliationBill, 0, len(rows))
	var total, totalQuota int64
	for _, row := range rows {
		total, totalQuota = row.Total, row.TotalQuota
		if row.HasItem != nil {
			items = append(items, row.ReconciliationBill)
		}
	}
	return items, total, totalQuota, nil
}

func GetReconciliationBills(
	ctx context.Context,
	filter dto.ReconciliationFilter,
	offset int,
	limit int,
) ([]dto.ReconciliationBill, error) {
	groupedSQL, args, err := buildReconciliationGroupedSQL(ctx, filter, true)
	if err != nil {
		return nil, err
	}
	querySQL := groupedSQL + " ORDER BY period DESC, username ASC, model_name ASC, user_id ASC"
	queryArgs := append([]any(nil), args...)
	if limit > 0 {
		querySQL += " LIMIT ?"
		queryArgs = append(queryArgs, limit)
	}
	if offset > 0 {
		querySQL += " OFFSET ?"
		queryArgs = append(queryArgs, offset)
	}

	items := make([]dto.ReconciliationBill, 0)
	err = LOG_DB.WithContext(ctx).Raw(querySQL, queryArgs...).Scan(&items).Error
	return items, err
}

func reconciliationOptionSearchPattern(keyword string) string {
	escaped := strings.NewReplacer(
		"!", "!!",
		"%", "!%",
		"_", "!_",
	).Replace(strings.TrimSpace(keyword))
	return "%" + escaped + "%"
}

func appendReconciliationUserOptionFilters(
	builder *strings.Builder,
	args *[]any,
	keyword string,
	userID int,
	alias string,
) {
	if userID > 0 {
		builder.WriteString(" AND " + alias + ".user_id = ?")
		*args = append(*args, userID)
	}
	keyword = strings.TrimSpace(keyword)
	if keyword == "" {
		return
	}
	pattern := reconciliationOptionSearchPattern(keyword)
	if numericID, err := strconv.Atoi(keyword); err == nil && numericID > 0 {
		builder.WriteString(" AND (" + alias + ".username LIKE ? ESCAPE '!' OR " + alias + ".user_id = ?)")
		*args = append(*args, pattern, numericID)
		return
	}
	builder.WriteString(" AND " + alias + ".username LIKE ? ESCAPE '!'")
	*args = append(*args, pattern)
}

func buildReconciliationUserOptionsSQL(
	ctx context.Context,
	keyword string,
	userID int,
) (string, []any, error) {
	state, err := GetReconciliationArchiveState(ctx)
	if err != nil {
		return "", nil, err
	}

	// A daily MAX(username) is sufficient for display, but not for searching
	// historical aliases. Search the retained logs when a keyword is supplied.
	useSummary := state != nil && strings.TrimSpace(keyword) == ""
	sources := make([]string, 0, 2)
	args := make([]any, 0, 8)
	var rawBuilder strings.Builder
	rawBuilder.WriteString("SELECT l.user_id, l.username FROM logs AS l WHERE l.type = ? AND l.user_id > 0")
	args = append(args, LogTypeConsume)
	if useSummary {
		rawBuilder.WriteString(" AND (l.created_at < ? OR l.created_at >= ?)")
		args = append(args, state.SummaryStart, reconciliationArchiveEndExclusive(state))
	}
	appendReconciliationUserOptionFilters(&rawBuilder, &args, keyword, userID, "l")
	sources = append(sources, rawBuilder.String())

	if useSummary {
		var summaryBuilder strings.Builder
		summaryBuilder.WriteString("SELECT s.user_id, s.username FROM reconciliation_daily_summaries AS s WHERE s.user_id > 0 AND s.day_start >= ? AND s.day_start < ?")
		args = append(args, state.SummaryStart, reconciliationArchiveEndExclusive(state))
		appendReconciliationUserOptionFilters(&summaryBuilder, &args, keyword, userID, "s")
		sources = append(sources, summaryBuilder.String())
	}

	return "SELECT user_id, COALESCE(MAX(NULLIF(username, '')), '') AS username FROM (" +
		strings.Join(sources, " UNION ALL ") + ") AS reconciliation_user_sources GROUP BY user_id", args, nil
}

func GetReconciliationUserOptions(
	ctx context.Context,
	keyword string,
	userID int,
	offset int,
	limit int,
) ([]dto.ReconciliationUserOption, int64, error) {
	groupedSQL, args, err := buildReconciliationUserOptionsSQL(ctx, keyword, userID)
	if err != nil {
		return nil, 0, err
	}
	var total int64
	var countResult struct {
		Total int64
	}
	if err := LOG_DB.WithContext(ctx).
		Raw("SELECT COUNT(*) AS total FROM ("+groupedSQL+") AS reconciliation_users", args...).
		Scan(&countResult).Error; err != nil {
		return nil, 0, err
	}
	total = countResult.Total

	items := make([]dto.ReconciliationUserOption, 0)
	querySQL := groupedSQL + " ORDER BY username ASC, user_id ASC"
	queryArgs := append([]any(nil), args...)
	if limit > 0 {
		querySQL += " LIMIT ?"
		queryArgs = append(queryArgs, limit)
	}
	if offset > 0 {
		querySQL += " OFFSET ?"
		queryArgs = append(queryArgs, offset)
	}
	err = LOG_DB.WithContext(ctx).Raw(querySQL, queryArgs...).Scan(&items).Error
	return items, total, err
}

func appendReconciliationModelOptionFilter(builder *strings.Builder, args *[]any, keyword string, alias string) {
	keyword = strings.TrimSpace(keyword)
	if keyword != "" {
		builder.WriteString(" AND " + alias + ".model_name LIKE ? ESCAPE '!'")
		*args = append(*args, reconciliationOptionSearchPattern(keyword))
	}
}

func buildReconciliationModelOptionsSQL(ctx context.Context, keyword string) (string, []any, error) {
	state, err := GetReconciliationArchiveState(ctx)
	if err != nil {
		return "", nil, err
	}

	sources := make([]string, 0, 2)
	args := make([]any, 0, 6)
	var rawBuilder strings.Builder
	rawBuilder.WriteString("SELECT l.model_name FROM logs AS l WHERE l.type = ? AND l.model_name <> ''")
	args = append(args, LogTypeConsume)
	if state != nil {
		rawBuilder.WriteString(" AND (l.created_at < ? OR l.created_at >= ?)")
		args = append(args, state.SummaryStart, reconciliationArchiveEndExclusive(state))
	}
	appendReconciliationModelOptionFilter(&rawBuilder, &args, keyword, "l")
	sources = append(sources, rawBuilder.String())

	if state != nil {
		var summaryBuilder strings.Builder
		summaryBuilder.WriteString("SELECT s.model_name FROM reconciliation_daily_summaries AS s WHERE s.model_name <> '' AND s.day_start >= ? AND s.day_start < ?")
		args = append(args, state.SummaryStart, reconciliationArchiveEndExclusive(state))
		appendReconciliationModelOptionFilter(&summaryBuilder, &args, keyword, "s")
		sources = append(sources, summaryBuilder.String())
	}

	return "SELECT model_name FROM (" + strings.Join(sources, " UNION ALL ") +
		") AS reconciliation_model_sources GROUP BY model_name", args, nil
}

func GetReconciliationModelOptions(
	ctx context.Context,
	keyword string,
	offset int,
	limit int,
) ([]dto.ReconciliationModelOption, int64, error) {
	groupedSQL, args, err := buildReconciliationModelOptionsSQL(ctx, keyword)
	if err != nil {
		return nil, 0, err
	}
	var countResult struct {
		Total int64
	}
	if err := LOG_DB.WithContext(ctx).
		Raw("SELECT COUNT(*) AS total FROM ("+groupedSQL+") AS reconciliation_models", args...).
		Scan(&countResult).Error; err != nil {
		return nil, 0, err
	}

	items := make([]dto.ReconciliationModelOption, 0)
	querySQL := groupedSQL + " ORDER BY model_name ASC"
	queryArgs := append([]any(nil), args...)
	if limit > 0 {
		querySQL += " LIMIT ?"
		queryArgs = append(queryArgs, limit)
	}
	if offset > 0 {
		querySQL += " OFFSET ?"
		queryArgs = append(queryArgs, offset)
	}
	err = LOG_DB.WithContext(ctx).Raw(querySQL, queryArgs...).Scan(&items).Error
	return items, countResult.Total, err
}
